<?php
if(!defined('BC_CRYPTO_DASHBOARD_ROLE')){http_response_code(404);exit;}
header('Cache-Control: no-store, private, max-age=0');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);header('Allow: GET');exit;}
require_once __DIR__.'/bc-crypto-dashboard.php';
$role=BC_CRYPTO_DASHBOARD_ROLE;
$actor=$role==='platform'?($get_logged_spadmin_details??null):($role==='vendor'?($get_logged_admin_details??null):($get_logged_user_details??null));
try{$identity=bc_crypto_dashboard_identity($role,$actor);}catch(Throwable $e){http_response_code(403);exit('Access denied. Complete required account security checks.');}
$env=$_GET['environment']??'mainnet';
if(!is_string($env)||!in_array($env,['testnet','mainnet'],true)){http_response_code(400);exit('Invalid environment.');}
$receipt=null;
if(isset($_GET['deposit_id'])){
    try{$receipt=bc_crypto_dashboard_receipt($identity,$env,$_GET['deposit_id']);}catch(Throwable $ex){http_response_code(400);exit('Invalid receipt request.');}
    if(!$receipt['available']){http_response_code(503);exit('Receipt data unavailable. No settlement status can be inferred.');}
    if(!$receipt['rows']){http_response_code(404);exit('Receipt not found.');}
}
$model=bc_crypto_dashboard_load($identity,$env);$customer=$role==='user';
$e=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');};
if($customer){require_once __DIR__.'/bc-plate-app.php';bc_app_head('Crypto overview');bc_app_sidebar();bc_app_topbar(['title'=>'Crypto overview']);}
else{$area=$role==='platform'?'spadmin':'admin';require_once __DIR__.'/bc-plate-admin.php';bc_adm_head('Crypto operations',['area'=>$area]);bc_adm_sidebar(['area'=>$area]);bc_adm_topbar(['area'=>$area,'title'=>'CRYPTO OPERATIONS','crumb'=>'Crypto / Overview']);}
?>
